import 'dart:convert';
import 'package:flutter/services.dart';

class PaymentIcons {
  static const String _bhimBase64 =
      '';

  /// Safely loads the BHIM icon from assets, with embedded base64 fallback
  /// in case the running app was hot-restarted before a full rebuild.
  static Future<Uint8List> loadBhimIcon() async {
    try {
      final data = await rootBundle.load('assets/icons/Bhim.png');
      return data.buffer.asUint8List();
    } catch (_) {
      return base64Decode(_bhimBase64);
    }
  }
}
